        Runtime original(compile(source)),restored(compile(source)),again(compile(source));for(auto* runtime:{&original,&restored,&again}){runtime->bindSleep("Yield");runtime->initialize();}auto argument=original.integer(7);original.start("root",std::span<const Value>(&argument,1));original.advanceThreads(.109375);auto globals=original.encodePrimitiveGlobals();auto snapshot=original.snapshotSleepingThread();require(snapshot.remaining==.015625 && snapshot.execution.frames.size()==2 && snapshot.execution.frames[1].locals.at(1).elements.at(5).bits==7,"Nested sleeping state was not captured");
