    test("sleep_snapshot_rejects_identity_collisions",[]{std::string source=std::string(waitNative)+"type unit extends handle\nfunction work takes unit first, unit second returns nothing\ncall Yield(0.125)\nendfunction\n";Runtime original(compile(source)),restored(compile(source));for(auto* r:{&original,&restored}){r->bindSleep("Yield");r->initialize();}Value args[]{original.handle("unit",17),original.handle("unit",18)};original.start("work",args);rejects([&]{original.snapshotSleepingThread([](auto,auto){return 7u;});},"handle mapping");auto snapshot=original.snapshotSleepingThread([](auto,std::uint32_t id){return id+1000;});rejects([&]{restored.restoreSleepingThread(snapshot,[](auto,auto){return 99u;});},"handle mapping");auto forged=snapshot;forged.handlesMapped=false;rejects([&]{restored.restoreSleepingThread(forged,[](auto,auto id){return id;});},"handle decoder");require(original.threadCount()==1 && !restored.threadCount(),"Rejected mapping changed script execution");});
    test("sleep_snapshot_rejects_unrestored_context",[]{std::string source=std::string(waitNative)+"function root takes nothing returns nothing\ncall Yield(0.125)\nendfunction\n";Runtime contexts(compile(source));contexts.bindSleep("Yield");contexts.threadHooks({[](auto,auto){},[](auto,auto){},[](auto){}});contexts.initialize();contexts.start("root");rejects([&]{contexts.snapshotSleepingThread();},"without thread contexts");Runtime multiple(compile(source));multiple.bindSleep("Yield");multiple.initialize();multiple.start("root");multiple.start("root");rejects([&]{multiple.snapshotSleepingThread();},"one direct sleeping execution");require(contexts.threadCount()==1 && multiple.threadCount()==2,"Rejected snapshot changed live threads");});
    test("sleep_context_restore_failure_cleanup",[]{std::string source=std::string(waitNative)+"globals\ninteger result=0\nendglobals\nfunction root takes nothing returns nothing\ncall Yield(0.125)\nset result=7\nendfunction\n";Runtime original(compile(source)),restored(compile(source));for(auto* r:{&original,&restored}){r->bindSleep("Yield");r->initialize();}original.threadHooks({[](auto,auto){},[](auto,auto){},[](auto){}});std::set<ThreadId> contexts;restored.threadHooks({[&](auto id,auto){contexts.insert(id);},[](auto,auto){},[&](auto id){contexts.erase(id);}});auto id=original.start("root");auto snapshot=original.snapshotSleepingThread({},[&](auto captured){require(captured==id,"Wrong captured context thread");});rejects([&]{restored.restoreSleepingThread(snapshot,{},[](auto){throw std::runtime_error("context rejected");});},"context rejected");require(!restored.threadCount() && contexts.empty(),"Failed context restore retained a thread or context");bool installed=false;restored.restoreSleepingThread(snapshot,{},[&](auto){installed=true;});restored.advanceThreads(.125);require(installed && restored.global("result").bits==7 && !restored.threadCount(),"Retry after context restore failure did not complete");});
    test("restore_parallel_sleeping_threads",[]{std::string source=std::string(waitNative)+"globals\ninteger trace=0\nendglobals\nfunction a takes nothing returns nothing\ncall Yield(0.125)\nset trace=trace*10+1\nendfunction\nfunction b takes nothing returns nothing\ncall Yield(0.0625)\nset trace=trace*10+2\nendfunction\nfunction c takes nothing returns nothing\ncall Yield(0.125)\nset trace=trace*10+3\nendfunction\n";Runtime original(compile(source)),restored(compile(source)),invalid(compile(source));for(auto* r:{&original,&restored,&invalid}){r->bindSleep("Yield");r->initialize();}original.start("a");original.start("b");original.start("c");original.advanceThreads(.03125);auto globals=original.encodePrimitiveGlobals();auto batch=original.snapshotSleepingThreads();require(batch.threads.size()==3 && !batch.sources.empty() && batch.threads[0].sources.empty(),"Sleeping batch did not share source identity");auto broken=batch;broken.threads[1].execution.frames.back().pc=0;rejects([&]{invalid.restoreSleepingThreads(broken);},"call frame");require(!invalid.threadCount() && !invalid.global("trace").bits,"Failed batch retained a partial continuation");restored.restorePrimitiveGlobals(globals.bytes);restored.threadClock(20);auto ids=restored.restoreSleepingThreads(batch);require(ids.size()==3 && ids[0]<ids[1] && ids[1]<ids[2],"Restored thread order differs");restored.advanceThreads(20.03125);require(restored.global("trace").bits==2,"Earlier wake was not preserved");restored.advanceThreads(20.09375);require(restored.global("trace").bits==213 && !restored.threadCount(),"Same-time wake order differs");original.advanceThreads(.0625);original.advanceThreads(.125);require(original.global("trace").bits==213,"Original and restored schedules disagree");});
    test("sleep_batch_rejects_join_without_losing_threads",[]{std::string source=std::string(waitNative)+"native Join takes code action returns nothing\nglobals\ninteger result=0\nendglobals\nfunction child takes nothing returns nothing\ncall Yield(0.125)\nset result=1\nendfunction\nfunction parent takes nothing returns nothing\ncall Join(function child)\nset result=2\nendfunction\n";Runtime r(compile(source));r.bindSleep("Yield");r.bind("Join",[](auto& vm,auto args){auto child=vm.start(args[0]);vm.waitThread(child);return vm.nothing();});r.initialize();r.start("parent");require(r.threadCount()==2,"Join fixture did not suspend both threads");rejects([&]{r.snapshotSleepingThreads();},"direct sleeping execution");require(r.threadCount()==2,"Rejected batch changed live threads");r.advanceThreads(.125);require(r.global("result").bits==2 && !r.threadCount(),"Rejected batch interrupted joined execution");});
    test("native_stack_and_cooperative_cancellation",[]{int live=0,destroyed=0,after=0;Runtime r(compile(std::string(waitNative)+"native Bridge takes code action returns nothing\nfunction child takes nothing returns nothing\ncall Yield(0.03125)\nendfunction\nfunction root takes nothing returns nothing\ncall Bridge(function child)\nendfunction\n"));bindWait(r);r.bind("Bridge",[&](auto& vm,auto args){++live;struct Guard{int& live;int& destroyed;~Guard(){--live;++destroyed;}}guard{live,destroyed};vm.invoke(args[0]);++after;return vm.nothing();});r.initialize();r.start("root");require(live==1 && !destroyed,"Native stack was discarded");r.advanceThreads(2./32);require(!live && destroyed==1 && after==1,"Native continuation did not return");r.start("root");r.cancelThreads();require(!live && destroyed==2 && after==1 && !r.threadCount(),"Cancellation did not unwind native resources");});
