    test("structured_thread_entries",[]{Runtime r(compile(std::string(waitNative)+"globals\ninteger result=0\nendglobals\nfunction work takes integer n returns nothing\ncall Yield(0.125)\nset result=n\nendfunction\nfunction immediate takes nothing returns integer\nset result=99\nreturn 3\nendfunction\n"));bindWait(r);r.initialize();r.pauseThreads(true);auto value=r.integer(42);auto id=r.start("work",std::span<const Value>(&value,1));auto anonymous=r.start([&]{});auto pending=r.inspectThreads();require(pending.size()==2 && pending[0].thread==id && pending[0].runtime && pending[0].structured && pending[0].function==r.module().functionId("work") && pending[0].arguments.size()==1 && pending[0].arguments[0].bits==42 && pending[0].state==ThreadState::Ready && pending[1].thread==anonymous && !pending[1].structured,"Paused task metadata differs");r.pauseThreads(false);r.advanceThreads(0);pending=r.inspectThreads();require(pending.size()==1 && pending[0].thread==id && pending[0].state==ThreadState::Sleeping,"Sleeping structured task was not retained");r.advanceThreads(.125);require(r.global("result").bits==42 && r.inspectThreads().empty(),"Structured entry did not execute or clean up");r.startDiscard("immediate");require(r.global("result").bits==99 && r.inspectThreads().empty(),"Discarding a return value changed execution");r.pauseThreads(true);r.start("work",std::span<const Value>(&value,1));r.cancelThreads();require(r.inspectThreads().empty(),"Cancellation retained structured task");});
    test("structured_cross_runtime_code_owner",[]{std::string source=std::string(waitNative)+"native Store takes code action returns nothing\nfunction action takes nothing returns nothing\ncall Yield(0.125)\nendfunction\nfunction save takes nothing returns nothing\ncall Store(function action)\nendfunction\n";Runtime map(compile(source)),ai(compile(source));Value callback;bindWait(map);map.bind("Store",[&](auto& vm,auto args){callback=args[0];return vm.nothing();});map.initialize();ai.inheritNatives(map);ai.shareThreads(map);ai.initialize();ai.invoke("save");auto id=map.start(callback);auto mapId=map.start("action");auto owned=ai.inspectThreads(),local=map.inspectThreads();require(owned.size()==1 && owned[0].thread==id && owned[0].structured && owned[0].function==ai.module().functionId("action") && local.size()==1 && local[0].thread==mapId && owned[0].runtime!=local[0].runtime,"Shared scheduler lost runtime ownership");map.advanceThreads(.125);require(ai.inspectThreads().empty() && map.inspectThreads().empty(),"Completed entries remained visible");});
